// Regenerates backend/supabase/functions/_shared/engine.js from the storefront pricing engine in src/store/commerce.js,
// so create-checkout-session prices a cart with exactly the code the shopper's browser ran (discounts → shipping → tax).
// Run after changing src/store/commerce.js or src/store/admin/discounts.js:  node backend/scripts/gen-engine.mjs
// (tests/backend.test.js fails when the generated file is out of date.)
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { commerceEngineSource } from '../../src/store/commerce.js';

export const ENGINE_PATH = fileURLToPath(new URL('../supabase/functions/_shared/engine.js', import.meta.url));

export function engineModule() {
  return `// @ts-self-types="./engine.d.ts"
// GENERATED by backend/scripts/gen-engine.mjs from src/store/commerce.js (commerceEngineSource) — do not edit by hand.
${commerceEngineSource()}export { CK };
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  await writeFile(ENGINE_PATH, engineModule());
  console.log('wrote', ENGINE_PATH);
}
